Future<List<Item>> enrich(List<String> ids, Repository repository) async {
  final allItems = await repository.loadMany(ids);
  return allItems.where((item) => item.active && item.owner?.enabled ?? false).toList();
}

for (final id in ids) {
  final item = await repository.load(id);
  if (item.active && item.owner?.enabled == true) {
    results.add(item);
  }
}

