func Enrich(ids []int64, repo Repository) []Item {
	results := []Item{}
	for _, id := range ids {
		item := repo.Load(id)
		if item.Active && item.Owner != nil && item.Owner.Enabled {
			results = append(results, item)
		}
	}
	return results
}

