test('enrich filters items based on active status and owner enablement', () async {
  final repo = MockRepository();
  final item1 = Item(id: '1', active: true, owner: Owner(enabled: true));
  final item2 = Item(id: '2', active: false, owner: Owner(enabled: true));
  final item3 = Item(id: '3', active: true, owner: Owner(enabled: false));
  final item4 = Item(id: '4', active: true, owner: null);

  when(repo.load('1')).thenAnswer((_) async => item1);
  when(repo.load('2')).thenAnswer((_) async => item2);
  when(repo.load('3')).thenAnswer((_) async => item3);
  when(repo.load('4')).thenAnswer((_) async => item4);

  final results = await enrich(['1', '2', '3', '4'], repo);

  expect(results, [item1]);
});

